fn solve(n: i8, m: i8) -> (i8, i8) {
    // We want:
    //   second = min(n, m)
    //   first  = (n + m - 1) - second  == max(n, m) - 1
    //
    // By inspecting which of n or m is smaller, we can avoid any chance
    // of overflow on n + m - 1 (since i8::MAX + i8::MAX - 1 would overflow).
    if n < m {
        // n is the smaller
        let second = n;
        let first = m - 1;
        (first, second)
    } else {
        // m is the smaller (or they're equal)
        let second = m;
        let first = n - 1;
        (first, second)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_solve_various() {
        let cases = [
            (1, 1, (0, 1)),  // 1+1-1 = 1; split into (0,1)
            (1, 5, (4, 1)),  // 1+5-1 = 5; split into (4,1)
            (5, 1, (4, 1)),  // same as above, order swapped
            (7, 3, (6, 3)),  // 7+3-1 = 9; split into (6,3)
            (3, 7, (6, 3)),  // same sum, swapped inputs
            (10, 10, (9, 10)), // equal inputs
        ];
        for &(n, m, expected) in &cases {
            assert_eq!(solve(n, m), expected);
            let (first, second) = solve(n, m);
            assert_eq!(first + second, n + m - 1);
            assert_eq!(second, n.min(m));
            assert_eq!(first, n.max(m) - 1);
        }
    }
}